def anti_shuffle(s):
    words = s.split(' ')
    ordered_words = []

    for word in words:
        if word:
            ordered_word = ''.join(sorted(word))
            ordered_words.append(ordered_word)
        else:
            ordered_words.append('')

    result = []
    space_index = 0

    for original_word in words:
        if original_word == '':
            result.append(' ')
        else:
            result.append(ordered_words[space_index])
            space_index += 1

    return ' '.join(result)

